from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.stack=[]; self.errs=[]
        self.void={'meta','link','br','img','input','hr','source','area','base','col','embed','param','track','wbr'}
    def handle_starttag(self,tag,attrs):
        if tag not in self.void: self.stack.append(tag)
        if tag=='a':
            d=dict(attrs)
            if d.get('href') is None: self.errs.append('a without href')
    def handle_endtag(self,tag):
        if not self.stack: self.errs.append('extra close '+tag); return
        if self.stack[-1]!=tag:
            self.errs.append(f'mismatch: expected {self.stack[-1]} got {tag} near line {self.getpos()[0]}')
            if tag in self.stack:
                while self.stack and self.stack[-1]!=tag: self.stack.pop()
                if self.stack: self.stack.pop()
        else: self.stack.pop()
p=P(); p.feed(open('index.html').read())
print('unclosed:',p.stack)
print('errors:',p.errs[:10])
EOF
